#!/bin/bash
# Palette bar: workspaces. Fills the bar's slots (space.1 … space.$SLOTS) with
# the workspaces AeroSpace has right now: the kept ones, any with windows and
# a new display's. Highlights the focused one and shows the app icons of
# every window on each. Settings arrive as variables:
#   SLOTS=12  SHOW_APPS=1|0  HIDE_EMPTY=1|0
#   ALL_DISPLAYS=0: each display's bar shows only the workspaces on it
#   (1: every bar shows them all)
# (generated by Palette; edits are replaced when the bar settings change)
export PATH="$PATH:/opt/homebrew/bin"
[ -f "$HOME/.config/palette/current/sketchybar.sh" ] && source "$HOME/.config/palette/current/sketchybar.sh"

# A new display: SketchyBar hears of it a moment before AeroSpace has made
# its workspace, so look again shortly (once; the trigger isn't a display_change).
if [ "$SENDER" = display_change ]; then
  (sleep 2; sketchybar --trigger aerospace_workspace_change) >/dev/null 2>&1 &
fi

ICON_MAP="$HOME/.config/sketchybar/helpers/icon_map.sh"
[ -f "$ICON_MAP" ] && source "$ICON_MAP"

app_icon() {
  if type __icon_map >/dev/null 2>&1; then
    __icon_map "$1"
    echo "$icon_result"
  else
    echo "•"
  fi
}

FOCUSED=${FOCUSED_WORKSPACE:-$(aerospace list-workspaces --focused 2>/dev/null)}
WINDOWS=$(aerospace list-windows --all --format '%{workspace}|%{app-name}' 2>/dev/null)
# workspace|display (SketchyBar's numbering of displays), in name order
PLACES=$(aerospace list-workspaces --monitor all --format '%{workspace}|%{monitor-appkit-nsscreen-screens-id}' 2>/dev/null | sort -t'|' -k1,1V)
[ -z "$PLACES" ] && exit 0 # AeroSpace isn't running: leave the bar as it is

args=()
slot=0
while IFS='|' read -r sid display; do
  [ -z "$sid" ] && continue
  has_windows=$(printf '%s\n' "$WINDOWS" | awk -F'|' -v s="$sid" '$1 == s { n++ } END { print n + 0 }')
  [ "${HIDE_EMPTY:-0}" = 1 ] && [ "$has_windows" = 0 ] && [ "$sid" != "$FOCUSED" ] && continue
  slot=$((slot + 1))
  [ "$slot" -gt "${SLOTS:-12}" ] && break
  item="space.$slot"

  icons=""
  if [ "${SHOW_APPS:-1}" = 1 ]; then
    while IFS= read -r app; do
      [ -z "$app" ] && continue
      icon=$(app_icon "$app")
      case " $icons " in
        *" $icon "*) ;;
        *) icons="$icons$icon " ;;
      esac
    done < <(printf '%s\n' "$WINDOWS" | awk -F'|' -v s="$sid" '$1 == s { print $2 }')
    icons=${icons% }
  fi

  where=all
  [ "${ALL_DISPLAYS:-0}" != 1 ] && [ -n "$display" ] && where=$display
  args+=(--set "$item" drawing=on display="$where" "icon=$sid" "click_script=aerospace workspace $(printf %q "$sid")")
  if [ "$sid" = "$FOCUSED" ]; then
    args+=(--set "$item" background.drawing=on icon.color=$DARK label.color=$DARK)
  else
    args+=(--set "$item" background.drawing=off icon.color=$GREY label.color=$FG)
  fi
  if [ -z "$icons" ]; then
    args+=(--set "$item" label.drawing=off icon.padding_right=8)
  else
    args+=(--set "$item" label.drawing=on "label=$icons" icon.padding_right=2)
  fi
done <<< "$PLACES"

# Slots nobody uses stay hidden.
for ((k = slot + 1; k <= ${SLOTS:-12}; k++)); do
  args+=(--set "space.$k" drawing=off)
done

sketchybar "${args[@]}"
